SourceCode.Declaration:
abstract class TFMInputHandler
{
    TFMRequestElement       request;
    XmlDocument             requestXml;

    TFMDocumentMessageId    messageId;
    TFMResponseElement      responseElement;
    XmlDocument             resultXml;
}

Method.Source:
/// <summary>
/// Method to set the request XML.
/// </summary>
/// <param name = "_xml">The request XML as a string.</param>
public void setRequest(TFMRequestElement _request)
{
    request = _request;
}

/// <summary>
/// Method to set the request XML.
/// </summary>
/// <param name = "_xml">The request XML as a string.</param>
public void setRequestXml(XmlDocument _xml)
{
    requestXml = _xml;
}

/// <summary>
/// get or set the message ID the current document has.
/// </summary>
/// <param name = "_msgID">The messageID to set. Datatype is GUID</param>
/// <returns>The current documents message ID as a GUID</returns>
public TFMDocumentMessageId parmMessageId(TFMDocumentMessageId _msgID = messageId)
{
    messageId = _msgID;
    return messageId;
}

/// <summary>
/// Extract values/parameters from the request XML.
/// </summary>
/// <returns>
/// true if the run method should continue processing the values.
/// </returns>
/// <remarks>
/// Should not throw any error/exception - rather return false.
/// May not do any processing.
/// Default is returns true
/// </remarks>
public boolean preProcess()
{
    return true;
}

/// <summary>
/// Return information about the request.
/// </summary>
/// <returns>
/// Information text
/// </returns>
/// <remarks>
/// Data should be retrieved in the preProcess method.
/// information is shown in document queue.
/// </remarks>
public TFMDocumentContentSubject getDocumentContentSubject()
{
    return '';
}

/// <summary>
/// Needs the TTS handling is requried. E.g. does this method post and change tables that requires the ttsbegin to be called outside the method.
/// </summary>
/// <returns></returns>
public boolean getTTSHandlingRequired()
{
    return false;
}
